<template>
  <DocumentLock
    :document_version="document_version"
    :trigger_document_lock="trigger_document_lock"
    :doc_id="docId"
    @setTriggerDocumentLock="setTriggerDocumentLock"
  />
  <SubHeader
    name="vertex_tax_verification"
    :label="$t('vertex_tax_verification')"
    :show_expiry_alert="true"
    :onSearch="false"
    :display_help_link="false"
  />

  <div class="row highlighted-back q-pl-md q-pr-md q-pb-md" v-if="error">
    <ErrorDocumentView />
  </div>
  <div class="row" v-else>
    <div class="full-width q-pl-lg q-pt-sm approve-mobile-v3">
      <div class="row mobile-device-approval">
        <div :class="showTaskPanel ? 'with-task-section' : 'full-width'">
          <q-splitter
            v-model="splitterModel"
            @update:model-value="windowResize()"
            class="approval-content-area q-pl-sm"
          >
            <template v-slot:before>

              <!-- Verification Status Banner -->
              <div
                class="status-banner q-ma-sm"
                :class="record.status === 'vertex_tax_rejected' ? 'status-banner--error' : 'status-banner--success'"
              >
                <div class="status-banner__indicator"></div>
                <div class="status-banner__content">
                  <q-icon
                    :name="record.status === 'vertex_tax_rejected' ? 'cancel' : 'check_circle'"
                    size="20px"
                    :color="record.status === 'vertex_tax_rejected' ? 'negative' : 'positive'"
                    class="q-mr-sm"
                  />
                  <div>
                    <div class="text-weight-medium text-body2">
                      {{ record.status === 'vertex_tax_rejected' ? $t('verification_failed') : $t('verification_successful') }}
                    </div>
                    <div class="text-caption text-grey-7">
                      {{ record.status === 'vertex_tax_rejected'
                        ? record.vertex_tax_verification?.message
                        : $t('all_line_items_verified_by_vertex')
                      }}
                    </div>
                  </div>
                </div>
              </div>

              <div class="back-white q-pa-sm" style="border-radius: 5px">
                <div class="full-width white-inputs">
                  <div class="full-width full-height">
                      <div class="full-width" v-if="renderComponent">
                        <template
                          v-for="(groupObj, groupIndex) in formLayout"
                          :key="`div-${groupIndex}`"
                        >
                          <div
                            class="full-width q-mb-lg not-sticky-area"
                            :data-group-id="groupIndex"
                            v-if="groupObj.rows.length > 0"
                          >
                            <div class="row q-pr-sm">
                              <div
                                class="col-12 secondary-c-text text-h6 text-weight-bold"
                              >
                                {{
                                  getFieldLabel(
                                    groupObj,
                                    '',
                                  )
                                }}
                              </div>
                            </div>

                            <div
                              class="full-width"
                              :data-fields-group-name="groupObj.name"
                            >
                              <template
                                v-for="(element, elementIndex) in groupObj.rows"
                                :key="`div-${elementIndex}`"
                              >
                                <div
                                  v-if="
                                    !element.is_hidden &&
                                    (element.visibile == undefined ||
                                      element.visibile)
                                  "
                                  class="display-block field-padding"
                                  :style="'width:' + element.elementWidth + '%'"
                                >
                                  <component
                                    :is="element.fieldType"
                                    :currentField="element"
                                    :isReadOnly="getReadOnlyStatus(element)"
                                    :fieldName="element.name"
                                    :groupIndex="groupIndex"
                                    :elementIndex="elementIndex"
                                    @inputClicked="htmlElementClick"
                                    @inputValueChanges="onInputValueChanges"
                                    @updateModel="updateModel"
                                  >
                                  </component>
                                </div>
                              </template>
                            </div>
                          </div>
                        </template>
                      </div>
                      <!-- END 2nd Panel fields -->
                  </div>
                </div>
              </div>
            </template>

            <template v-slot:separator>
              <div style="margin-left: 3px; top: 40%">
                <q-icon
                  name="drag_handle"
                  size="md"
                  class="icon-grey rotate-90-deg"
                />
              </div>
            </template>

            <template v-slot:after>
              <!-- Document Fields Panel -->

              <div class="row">
                <div
                  class="approval-width q-pl-sm approval-anotation-area scrolle-y"
                >
                  <div class="invisible absolute position-absolute">
                    <div class="row">
                      <div class="q-mr-auto">
                        <q-icon
                          class="up-arrow cursor-pointer"
                          @click="prevImage"
                          name="expand_less"
                          size="sm"
                        >
                          <q-tooltip>{{ $t('previous') }}</q-tooltip>
                        </q-icon>

                        <q-icon
                          class="down-arrow cursor-pointer"
                          @click="nextImage"
                          name="expand_more"
                          size="sm"
                        >
                          <q-tooltip>{{ $t('next') }}</q-tooltip>
                        </q-icon>

                        <span class="page-numbers"
                          >{{ currentPage() }}/{{ images.length }}
                          {{ $t('page_number_text') }}</span
                        >
                      </div>
                      <div class="panel-middle mobile-hide">
                        <span>{{ $t('vertex_tax_verification') }}</span>
                      </div>
                      <div class="panel-right mobile-hide">
                        <span
                          class="cursor-pointer q-mr-md text-uppercase"
                          @click="downloadFile"
                          >{{ $t('download') }}</span
                        >
                        <span class="doc-name">{{ record.filename }}</span>
                      </div>
                    </div>
                  </div>
                  <div class="full-width">
                    <div
                      class="full-width full-height"
                      id="image_container"
                      style="position: relative"
                    >
                      <img
                        :src="image + '?' + tokenQueryParam"
                        :width="imageWidth"
                        class="vertex-document-image"
                        alt="Document preview"
                      />
                    </div>
                  </div>
                </div>

                <div
                  class="column absolute-right q-ml-auto justify-between right-action-bar back-white"
                >
                  <div class="action-bar-items">
                    <q-btn
                      flat
                      size="20px"
                      class="validation-view-button v-p-0"
                      @click="openImageInSeparateWindow"
                    >
                      <Icon icon="mdi:fullscreen" width="20" height="20" />
                    </q-btn>
                    <TaskBtn
                      @btnClicked="
                        showTaskPanel = !showTaskPanel;
                        windowResize();
                      "
                    />
                    <q-separator class="separator-space" />
                  </div>
                  <div class="action-bar-bottom">
                    <q-separator class="q-mb-sm" />
                    <div class="q-my-auto">
                      <q-btn
                        flat
                        class="validation-view-button"
                      >
                        <Icon icon="mdi:file-multiple" width="20" height="20" />
                        <q-tooltip>
                          {{ currentPage() }} / {{ images.length }}
                        </q-tooltip>
                      </q-btn>
                    </div>
                    <q-input
                      outlined
                      dense
                      v-model="page"
                      class="validation-view-input"
                      @update:model-value="
                        (val: any) => {
                          pageChanged(val);
                        }
                      "
                      @blur="validatePageNumber"
                    ></q-input>
                    <span class="validation-view-button q-pt-md">{{
                      images.length
                    }}</span>
                    <div>
                      <q-btn
                        :disable="page == 1"
                        icon="keyboard_arrow_up"
                        flat
                        class="validation-view-page-button icon-grey"
                        @click="prevImage"
                      />
                      <q-btn
                        :disable="page == images.length"
                        icon="keyboard_arrow_down"
                        flat
                        class="validation-view-page-button icon-grey"
                        @click="nextImage"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </template>
          </q-splitter>
        </div>
        <div class="task-section" v-if="showTaskPanel">
          <TaskList
            @btnClicked="
              showTaskPanel = !showTaskPanel;
              windowResize();
            "
          />
        </div>
      </div>
    </div>

  </div>

  <Loader />
  <q-footer class="validation-status-bar back-white">
    <q-toolbar class="row justify-start">
      <span>{{ record.filename }}</span>
      <q-btn size="md" flat dense class="q-ml-xs" @click="downloadFile">
        <q-icon name="download" style="color: #8a8a8a" />
      </q-btn>
      <q-separator vertical class="q-mx-md" />
      <span class="footer-status-message">
        {{ $t('vertex_tax_verification') }}
      </span>
    </q-toolbar>
  </q-footer>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { Platform } from 'quasar';
import { storeToRefs } from 'pinia';
import { dynamicObj } from './assets';
import { DOC2API_URL } from 'src/pages/APIs';
import { downloadDocumentFile } from 'src/utils/download';
import helperUtil from 'src/utils/helperUtil';
import Loader from '../components/Loader.vue';
import helperMixin from '../mixins/helperMixin.js';
import { defineComponent, ref, computed } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import { isUndefinedOrNull } from 'src/utils/general';
import { documentDetailApiService } from 'src/services';
import { isEmptyString, objLen } from 'src/utils/general';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import TaskList from 'src/components/document/Tasks/List.vue';
import TaskBtn from 'src/components/document/Tasks/TaskBtn.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import ErrorDocumentView from 'src/pages/Errors/ErrorDocumentView.vue';
import Label from 'src/formBuilder/form_elements/FormElementLabel.vue';
import { cleanUpImagesUrl, cleanUpImagePath } from 'src/utils/viewImages';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';
import EnumInput from 'src/formBuilder/form_elements/FormElementEnumInput.vue';
import TextInput from 'src/formBuilder/form_elements/FormElementTextInput.vue';
import VertexPanel from 'src/formBuilder/form_elements/FormElementVertexPanel.vue';
import Button from 'src/formBuilder/form_elements/approval/FormElementApprovalButton.vue';
import HorizontalSeparator from 'src/formBuilder/form_elements/FormElementHorizontalSeparator.vue';
import ExtractedTableTabPanels from 'src/formBuilder/form_elements/approval/FormElementExtractedTableTabPanels.vue';
import {
  useDocumentStore,
  useFormBuilderStore,
  useDocAttributesStore,
  useSettingStore,
  useDocLockStore,
  useFieldValuesSettingsStore} from 'src/store/main';
import { CONSTANTS, layout_types, } from 'src/constants';
import DocumentLock from 'src/components/DocumentLock.vue';
import { useImageAuth } from 'src/composables/useImageAuth';
import Notes from 'src/formBuilder/form_elements/approval/FormElementNotes.vue';
import UserDropdown from 'src/formBuilder/form_elements/FormElementUserDropdown.vue';
import GroupDropdown from 'src/formBuilder/form_elements/FormElementGroupDropdown.vue';

const $ = document.querySelector.bind(document);

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil, displayFieldLabel],
  components: {
    
    DocumentLock,
    Notes,
    Loader,
    TaskBtn,
    TaskList,
    EnumInput,

    ErrorDocumentView,
    SubHeader,
    Label,
    Button,
    TextInput,
    HorizontalSeparator,
    ExtractedTableTabPanels,
    VertexPanel,
    UserDropdown,
    GroupDropdown,
  },
  data() {
    return {
      docId: '',
      imageWidth: 0,
      loading: false,
      renderComponent: ref(false),
      showTaskPanel: ref(false),
      splitterModel: ref(Platform.is.mobile ? 100 : 50),
    };
  },
  beforeRouteLeave: async function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    await this.releaseDocLock({ doc_id: this.record.doc_id });
    this.resetDocStore(to.fullPath);
    this.restoreBeforeLeave();
    await this.removeCache();
    next();
  },
  mounted: async function () {
    let doc_id = this.$route.params.id as string;
    this.getDocAnnotations(doc_id);
    await this.fetchAttributes(this.record.doc_type);
    this.getDocTypeAllSettings();

    window.addEventListener('resize', this.windowResize);

    this.acquireDocLock();
    this.init();

  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
  },
  methods: {
    openImageInSeparateWindow() {
      let route = this.$router.resolve({ path: '/po-image' });
      window.open(
        route.href,
        '_blank',
        'toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1000,height=1000',
      );
    },
    async init() {
      if (!this.$route.params.id) {
        this.$router.push('/dashboard');
      }

      this.docId = this.$route.params.id as string;
      await this.getInvoiceDataByDocId(this.docId);
      await this.getFieldsPermissions(this.record.doc_type);

      const layoutTypes = layout_types.vertex_tax_verification;

      await this.startSettingsFetch();
      await this.getFormBuilderLayout(layoutTypes);
      await this.populateListsAndValues();

      this.renderComponent = true;

      this.handleImageBaseURL();
      this.image =
        this.baseUrl + '/' + cleanUpImagePath(this.record.images[0].path);
      this.images = cleanUpImagesUrl(this.record.images);

      // set the width of image
      this.windowResize();
    },

    async getInvoiceDataByDocId(docId: string) {
      try {
        this.showLoading();
        await this.getDocumentById(docId);
        if (!this.record.doc_id) {
          throw { message: 'INVALID_DOCUMENT' };
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    createEmptyField(name: string, type = '', value: any = '') {
      if (type == 'checkbox') {
        value = false;
      }
      return {
        confidence: 0,
        name: name,
        value: value,
        formatted_value: value,
        content: value,
      };
    },
    async getFieldsPermissions(document_type: string) {
      try {
        if (!document_type) {
          return;
        }
        const response = await documentDetailApiService.getFieldsPermissionsApi(document_type);
        if (!response.success) {
          throw { message: response.message };
        }

        this.field_permissions = response.field_permissions;
        this.general_permissions = response.general;
        this.prepareFieldPermissions(response.field_permissions);
        this.prepareTablePermissions(response.table_column_permissions);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    prepareTablePermissions(permissions: any) {
      if (!permissions) {
        return;
      }

      for (const [index, item] of Object.entries(permissions)) {
        const permission = item as any;
        let name = permission.name.toLowerCase();
        this.tablePermissions[name] = { id: index, access: permission.access };
      }
    },
    prepareFieldPermissions(permissions: any) {
      if (!permissions) {
        return;
      }

      for (const [index, item] of Object.entries(permissions)) {
        const permission = item as any;
        let name = permission.name.toLowerCase();
        this.fieldPermissions[name] = { id: index, access: permission.access };
      }
    },

    isModelReady() {
      return objLen(this.formBuilderConfigModel) !== 0;
    },
    htmlElementClick(fieldName: string) {
      // Handle form builder element clicks
    },
    onInputValueChanges(field_name: string, fieldType: string) {
      if (fieldType == formBuilderInputTypes.NOTES) {
        return;
      }
      this.updateLocalModel(field_name);
      this.updateImportJson(field_name);
    },

    updateLocalModel(field_name: string) {
      if (!this.formBuilderModel.hasOwnProperty(field_name)) {
        return;
      }
      this.formBuilderModel[field_name].value =
        this.formBuilderModel[field_name].formatted_value;
    },

    updateImportJson(
      connectionId: string,
      coordinates?: any,
      page?: number,
      extractionMethod = '',
    ) {
      try {
        const found_field = this.record.fields.find(
          (field: any) => field.name === connectionId,
        ) as dynamicObj;
        if (!found_field) {
          this.record.fields.push({});

          const field_index = this.record.fields.length - 1;
          this.record.fields[field_index].name = connectionId;
          this.record.fields[field_index].content =
            this.formBuilderModel[connectionId].content;
          this.record.fields[field_index].formatted_value =
            this.formBuilderModel[connectionId].formatted_value;
          this.record.fields[field_index].value =
            this.formBuilderModel[connectionId].value;
          this.record.fields[field_index].original_value = '';
          this.record.fields[field_index].validation_code = '';
          this.record.fields[field_index].extraction_method = extractionMethod;
          this.record.fields[field_index].is_validated = true;
          this.record.fields[field_index].is_valid = true;
          this.record.fields[field_index].color = CONSTANTS.success_border_left;

          if (this.formBuilderModel[connectionId].multi_line === true) {
            this.record.fields[field_index].multi_line = true;
          } else {
            this.record.fields[field_index].multi_line = false;
          }

          if (coordinates) {
            this.record.fields[field_index].coords = coordinates;
          }

          if (page) {
            this.record.fields[field_index].page = page;
          }

          this.$emit('checkFieldInvalid', this.record.fields[field_index]);
          return;
        }

        // existing field
        if (!found_field.hasOwnProperty('original')) {
          found_field['original'] = Object.assign({}, found_field);
        }

        if (!found_field.hasOwnProperty('original_value')) {
          found_field['original_value'] = found_field.value;
        }

        if (coordinates || coordinates === null) {
          found_field.coords = coordinates;
        }

        if (page) {
          found_field.page = page;
        }
        if (extractionMethod) {
          found_field.extraction_method = extractionMethod;
        }

        found_field.is_valid = true;
        found_field.is_validated = true;

        let field = this.formBuilderModel[connectionId];
        found_field.formatted_value = field.formatted_value;
        found_field.value = field.value ? field.value : field.formatted_value;
        found_field.content = field.content;

        if (!(field.hasOwnProperty('api_save') && field.api_save)) {
          found_field.value = field.formatted_value;
        }

        if (
          isUndefinedOrNull(found_field.formatted_value) ||
          isEmptyString(found_field.formatted_value)
        ) {
          found_field.content = found_field.formatted_value;
        }

        if (
          this.formBuilderModel[connectionId] &&
          this.formBuilderModel[connectionId].hasOwnProperty('multi_line') &&
          this.formBuilderModel[connectionId].multi_line === true
        ) {
          found_field.multi_line = true;
        } else {
          found_field.multi_line = false;
        }

        this.formBuilderModel[connectionId].is_valid = found_field.is_valid;
        this.formBuilderModel[connectionId].is_validated =
          found_field.is_validated;
        this.$emit('checkFieldInvalid', found_field);
      } catch (err) {
        logError(err);
      }
    },

    windowResize() {
      setTimeout(() => {
        let imageElm = $('#image_container') as HTMLElement;
        this.imageWidth = imageElm.offsetWidth;
      }, 20);
    },

    currentPage() {
      return this.page;
    },
    prevImage() {
      let new_page_number = this.page - 1;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
    },

    nextImage() {
      let new_page_number = this.page + 1;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
    },

    getImagePath(page_number: number) {
      let path = '';
      for (const [key, image] of Object.entries(this.images)) {
        let imageInfo = image as dynamicObj;
        if (imageInfo.pageNumber === page_number) {
          path = imageInfo.path;
        }
      }

      return path;
    },

    updateImage(page_number: number, path: string) {
      if (!path || path === '') {
        return;
      }
      this.image = this.baseUrl + '/' + cleanUpImagePath(path);
      this.page = page_number;
    },
    handleImageBaseURL() {
      if (!this.record.images[0]) {
        return;
      }
      if (this.record.images[0].path.match(/doc2/g)) {
        this.baseUrl = DOC2API_URL;
      }
    },
    downloadFile() {
      downloadDocumentFile(this.docId, this.record.filename, this.tokenQueryParam, '.pdf');
    },
    makeModel_v2() {
      return new Promise((resolve, reject) => {
        let data: any = {};
        if (this.record !== undefined) {
          this.record.fields.forEach((value: any, index: any) => {
            data[value.name] = value;
          });

          // prepare the list with updated field settings
          let layoutSettings = this.getUpdatedFieldSettings();

          for (let [index, group] of this.formLayout.entries()) {
            for (let fieldDef of group.rows) {
              let field_name = fieldDef.hasOwnProperty('field_name')
                ? fieldDef.field_name
                : fieldDef.name;

              // replace setting with updated field settings
              if (layoutSettings.hasOwnProperty(field_name)) {
                fieldDef = Object.assign(
                  fieldDef,
                  this.cleanLayoutSettings(layoutSettings[field_name]),
                );
              }

              this.prepareModel(fieldDef, data[field_name], field_name);
            }
          }
          this.$forceUpdate();
        }

        resolve('done');
      });
    },
    prepareModel(fieldDef: any, field_model: any, field_name: string) {
      if (!field_model) {
        field_model = this.createEmptyField(field_name, fieldDef.input_type);
      }
      let fieldType = fieldDef.input_type
        ? fieldDef.input_type
        : fieldDef.fieldType;
      if (!fieldType) {
        return;
      }

      if (
        !fieldDef.hasOwnProperty('tabIndex') ||
        isUndefinedOrNull(fieldDef.tabIndex)
      ) {
        fieldDef.tabIndex = 0;
      }

      this.cleanCheckboxValue(field_model, fieldType.toLowerCase());

      this.formBuilderModel[field_name] = {};
      this.formBuilderConfigModel[field_name] = {};

      this.formBuilderModel[field_name] = Object.assign({}, field_model);
      this.formBuilderConfigModel[field_name] = Object.assign({}, fieldDef);

      if (field_model.hasOwnProperty('is_required')) {
        this.formBuilderConfigModel[field_name].is_required =
          field_model.is_required;
      }

      this.handleListofValues(field_name);
    },
    cleanCheckboxValue(field_model: any, type: string) {
      if (type != 'checkbox' && field_model.fieldType != 'CheckBox') {
        return;
      }

      if (
        field_model.formatted_value == 'true' ||
        field_model.formatted_value == true ||
        field_model.formatted_value == 'Y'
      ) {
        field_model.formatted_value = true;
      } else {
        field_model.formatted_value = false;
      }
    },
    handleListofValues(field_name: string) {
      if (!this.formBuilderConfigModel[field_name].list_of_values) {
        return;
      }

      this.addNameToLovList(
        this.formBuilderConfigModel[field_name].list_of_values,
      );
    },
    cleanLayoutSettings(layoutSetting: any): any {
      delete layoutSetting.name;
      delete layoutSetting.field;
      delete layoutSetting.field_name;
      delete layoutSetting.field_type;

      // remove the title as it might be changed from layout builder
      delete layoutSetting.title;
      delete layoutSetting.translation_key;
      delete layoutSetting.is_readonly;

      return layoutSetting;
    },

    async getFormBuilderLayout(layoutType = '') {
      try {
        const prams = {
          layout_type: layoutType,
          doc_type: this.record.doc_type,
          doc_origin: this.record.doc_origin,
          include_layout_json: true,
        };
        await this.getLayoutTemplate(prams);

        if (this.formLayout) {
          await this.makeModel_v2();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    getUpdatedFieldSettings(): any {
      let layoutSettings: any = {};
      let groups = JSON.parse(JSON.stringify(this.record.layout.groups));

      groups.forEach((group: any, index: any) => {
        group.rows.forEach((row: any, index: any) => {
          row.forEach((subRow: any, index: any) => {
            let field_name = subRow.field_name;
            layoutSettings[field_name] = subRow;
          });
        });
      });

      return layoutSettings;
    },
    updateModel(newField: any) {
      return;
    },

    restoreBeforeLeave() {
      this.record = {};
      this.error = false;
      this.error_message = '';
      this.page = 1;
    },

    getReadOnlyStatus(element: dynamicObj) {
      if (element.name.startsWith('tab_panel_tables_')) {
        return true;
      }

      return element.is_readonly;
    },
    validatePageNumber() {
      if (!this.page) {
        this.page = 1;
        return;
      }

      if (this.page > this.images.length) {
        this.page = this.images.length;
      }

      this.pageChanged(this.page);
    },
    pageChanged(number: any) {
      if (!number || number == 0 || number > this.lastPageItem) {
        return;
      }

      this.updateImage(
        number,
        cleanUpImagePath(this.record.images[number - 1].path),
      );
    },

    goToDashboard() {
      this.$router.push('/dashboard');
    },

    setTriggerDocumentLock(isLocked: boolean) {
      this.trigger_document_lock = isLocked;
    },
  },
  setup() {
    let data: any = [];

    const doc_store = useDocumentStore();
    const {
      getDocumentById,
      getDocAnnotations,
      resetDocStore,
      removeCache,
    } = doc_store;
    const {
      record,
      error,
      error_message,
      page,
      tablePermissions,
      fieldPermissions,
      document_version,
    } = storeToRefs(doc_store);

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    const form_builder_store = useFormBuilderStore();
    form_builder_store.$reset();
    const {
      formBuilderModel,
      formLayout,
      formBuilderConfigModel,
    } = storeToRefs(form_builder_store);
    const { getLayoutTemplate } = form_builder_store;

    const doc_attribute_store = useDocAttributesStore();
    const { fetchAttributes, getDocTypeAllSettings } = doc_attribute_store;

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock, acquireDocLock } = doc_lock_store;

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { addNameToLovList, populateListsAndValues } =
      field_values_setting_store;

    return {
      user_settings,
      getDocumentById,
      fetchAttributes,
      getDocAnnotations,
      getLayoutTemplate,
      getDocTypeAllSettings,
      removeCache,
      addNameToLovList,
      startSettingsFetch,
      populateListsAndValues,

      tokenQueryParam,
      getTokenQueryParam: refreshTokenParam,
      page,
      error,
      error_message,
      record,
      image: '',
      images: data,
      baseUrl: DOC2API_URL,
      tablePermissions,
      fieldPermissions,
      field_permissions: ref({} as any),
      general_permissions: ref({} as any),
      formLayout,
      formBuilderModel,
      formBuilderConfigModel,
      trigger_document_lock: ref(false),
      document_version,
      releaseDocLock,
      acquireDocLock,
      resetDocStore,
    };
  },
});
</script>

